package com.styleconverter.runtime.layout

// FloatAvoidPlanTest — wave-53 lane L4 pins on the VERBATIM wave52-ship
// per-test IR (byte-identical to wave53-open). GENERATED by
// tools/titan/results/wave53-float-avoid/gen-pins.py from the .tmpl beside it:
// the literals at the bottom are the corpus files' bytes, and `verbatim`
// re-hashes each one. The BFC height h is INJECTED (a device measurement — a
// Compose Layout cannot run on the JVM). Pin ids P1–P8 follow PLAN.md §2 L4;
// the executed mutations are logged in tools/titan/results/wave53-float-avoid/
// _note.md. Twin: StyleConverterRuntimeTests/FloatAvoidPlanTests.swift.

import com.styleconverter.runtime.core.ir.IRComponent
import com.styleconverter.runtime.core.ir.IRDocumentDecoder
import com.styleconverter.runtime.core.renderer.SlotComposer
import java.io.File
import java.security.MessageDigest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assume.assumeTrue
